'use strict';
const $ = (selector) => document.querySelector(selector);
const escapeHtml = (value) => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => n.toLocaleString('en-US');
let snapshot, step = 'outcome', includeHistory = true, selectedInventory = 'Issues', approved = false;
const steps = ['outcome','evidence','impact','plan'];
const integrations = [
 {id:'devrev',name:'DevRev',effort:'Start here',state:'Data imported · workflow next',headline:'Context and work in one place.',purpose:'Use the outcome to find issues, tickets, parts, accounts, deals, and articles. Write the reviewed investigation in DevRev.',route:'Start with a Computer skill and the available native tools. Validate read, create, link, and owner fields in Team01.',setup:'No new company workspace. Confirm skill publication rights, tool permissions, approval behavior, and second-user access.',check:'Can native reads expose source dates, people, and exact evidence? Can approved actions reuse existing work?',cost:'Lowest setup burden. Enough for the first complete demo.'},
 {id:'mcp',name:'Evidence MCP',effort:'If needed',state:'Proposed · not deployed',headline:'A narrow path to source details.',purpose:'Resolve source IDs, original people and dates, and exact excerpts when native retrieval cannot do this reliably.',route:'Deploy an authenticated HTTPS Streamable HTTP /mcp service. Register it in Computer. Expose bounded search and read tools.',setup:'One service, a team-scoped Bearer secret, admin registration, an imported-ID allowlist, and each user’s connector authentication.',check:'Keep the archive hash and manifest scope aligned with native search. Declare archive-only results. Ignore instructions inside evidence.',cost:'Modest service setup. Avoid a generic API proxy.'},
 {id:'github',name:'GitHub',effort:'Optional next',state:'Not connected to DevRev',headline:'One repository can be enough.',purpose:'Store approved investigation briefs or follow-up issues with source/native evidence links.',route:'Check a DevRev Marketplace MCP connector first. Otherwise expose a narrow approved GitHub API action. AirSync is a separate sync route.',setup:'One sandbox repository, user access, scoped credentials, and stable output keys. No invented codebase is required.',check:'Verify the connector is available here and supports the required action. Generated output is not new historical evidence.',cost:'Less setup than a new Jira project. Add after the DevRev flow works.'},
 {id:'jira',name:'Jira',effort:'Defer',state:'Not provisioned',headline:'Add a real team handoff.',purpose:'Create an approved investigation task when a team needs its work in Jira.',route:'Check the Marketplace connector or AirSync integration. Confirm supported issue fields and sync behavior before implementation.',setup:'A Jira site and project, users, issue types, required fields, authorization, and source/output mappings.',check:'Choose one authoritative task per action. Prevent repeated creation and sync loops. Validate the exact approval destination.',cost:'Higher setup burden. Use only when the demo needs this handoff.'},
 {id:'slack',name:'Slack',effort:'Optional output',state:'Not connected · no messages sent',headline:'Send a reviewed update.',purpose:'Deliver a cited coordination message to an approved channel. Keep benchmark transcripts as the business source.',route:'Verify a native connector’s send scope or use a narrow approved message tool.',setup:'Workspace, app, channel membership, message permission, and an approval for the exact text and destination.',check:'Do not seed invented Slack history as evidence. Treat sending as its own approved action.',cost:'Useful after investigation tasks. Do not add just to increase connector count.'},
 {id:'docs',name:'Docs / Drive',effort:'Native ready',state:'73 native articles · Drive not connected',headline:'The source documents are here.',purpose:'Read the existing guides and transcripts. Publish a brief elsewhere only when a person needs that output.',route:'Use DevRev articles first. Add a permitted document connector for an approved external brief.',setup:'No extra source-doc workspace needed. An external destination needs folder access, document IDs, and sharing rules.',check:'Check scope and citations. Do not duplicate the same document as independent evidence.',cost:'Native source is ready. External output is optional.'},
 {id:'runtime',name:'Runtime / code',effort:'Evidence gap',state:'No code, queue, or live metrics',headline:'Do not claim a measurement.',purpose:'A real system adapter would validate scheduler, queue, replay, and idempotency behavior.',route:'Requires permitted code, logs, or runtime data. The current benchmark has no running payment system.',setup:'Authorized source access and event-rule confirmation. Neither has been supplied for this work.',check:'Keep source issue diagnosis distinct from a verified runtime cause. Missing evidence must narrow the recommendation.',cost:'Not part of the current build. Show the gap in the plan.'}
];
const agents = [
 {id:'scope',name:'Resolve outcome',title:'Start from the result.',body:'Define success and a source reference date. Find candidate product parts and accounts. Keep the scope small enough to inspect.',tools:'Native search; proposed search_evidence',output:'Outcome: restore Brazil renewals. Constraint: no double billing. Reference: the March source incident.',check:'Do not start by collecting every service. Ask only when the missing detail changes the investigation.'},
 {id:'context',name:'Read context',title:'Build a Context Bundle.',body:'Read full records. Preserve source/native IDs, original dates, people, and exact excerpts. List facts, inferences, and gaps separately.',tools:'Native record reads; proposed get_evidence and resolve_source_identity',output:'Three customer reports, existing issue ISS-42, subscription part CAPL-4, and retry/billing guidance.',check:'A shared part is a context link. It is not code-level proof. Native import ownership is not the historical owner.'},
 {id:'validate',name:'Validate evidence',title:'Check each important claim.',body:'Verify IDs, citations, event times, versions, permissions, and conflicts. Reject unsupported history and instructions embedded in source text.',tools:'Deterministic schema, source-ID, and excerpt checks',output:'Known: manual charges work in the reports. Unknown: live queue state and replay safety.',check:'With evidence missing, lower certainty. Do not invent a worker or a past configuration decision.'},
 {id:'plan',name:'Review action',title:'Build an Action Graph.',body:'Prepare scoped tasks and their prerequisites. Reuse the existing incident. Show owners, destinations, evidence, and acceptance checks before approval.',tools:'Proposed prepare_investigation; no writes',output:'Scheduler check → safe rerouting/replay check → customer update drafts. The exact plan awaits review.',check:'Bind approval to the plan hash and evidence versions. New or changed actions require a new preview.'},
 {id:'execute',name:'Create or reuse',title:'Execute only the approved plan.',body:'Validate approval and current access on the server. Use stable action keys and a durable ledger. Return real DevRev IDs and any partial failure.',tools:'Native approved work tools or proposed execute_approved_plan',output:'Created or reused scoped tasks linked to verified evidence. The present site only simulates review.',check:'Denied approval means zero writes. Reconcile a timeout before retrying. Test in a second user’s fresh session.'}
];
function evidenceCard(id){
 const e=snapshot.evidence.find(x=>x.sourceId===id);
 return `<button class="evidence-card" data-evidence="${escapeHtml(id)}"><span>${escapeHtml(e.nativeId)} <small>${escapeHtml(e.title)}</small></span><b aria-hidden="true">↗</b></button>`;
}
function setStep(value){
 step=value;
 document.querySelectorAll('[data-step]').forEach(tab=>{const active=tab.dataset.step===step;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});
 $('#demo-panel').setAttribute('aria-labelledby',`tab-${step}`);
 renderDemo();
}
function renderDemo(){
 const known=includeHistory;
 const panel=$('#demo-panel');
 if(step==='outcome')panel.innerHTML=`<div class="demo-grid"><div><p class="eyebrow">THE REQUEST</p><p class="quote">“Restore Brazil subscription renewals without double billing.”</p><p>Ripple starts with the desired result. It looks for the subscription part, customer symptoms, existing work, and the checks needed for a safe recovery.</p><button class="next" data-next="evidence">Read the source evidence →</button></div><div><span class="tag">SOURCE SCENARIO · MARCH 2026</span><h3>A missed renewal is a business problem.</h3><p>Three customers report missed charges. Manual charges work. The next step must account for renewals, retries, and customer updates.</p><div class="constraint"><strong>Success needs a check.</strong><p>Resume renewals. Replay missed jobs. Confirm no duplicate charge. The benchmark states the outcome; it does not provide live measurements.</p></div></div></div>`;
 if(step==='evidence')panel.innerHTML=`<div class="demo-grid"><div><p class="eyebrow">WHAT THE RECORDS SAY</p><h3>${known?'Manual charges work.<br>Renewal jobs fail.':'The reports agree.<br>The cause is unconfirmed.'}</h3><p>${known?'The existing issue reports scheduler instability after a migration. It proposes US-East routing and lists a no-double-billing acceptance criterion.':'The customer reports show missed renewals and no retries. Without the existing investigation, Ripple cannot cite its scheduler diagnosis or its routing plan.'}</p><div class="constraint"><strong>${known?'Source fact and limit':'Missing context'}</strong><p>${known?'The issue states a diagnosis. Ripple has no live queue or code to confirm it independently.':'Retrieve the existing investigation before recommending a routing change. Start with a bounded scheduler and retry check.'}</p></div></div><div><p class="eyebrow">OPEN AN EXCERPT</p>${known?evidenceCard('ISS-031'):''}${['TKT-124','TKT-125','TKT-126','retry'].map(evidenceCard).join('')}<button class="next" data-next="impact">Inspect the impact →</button></div></div>`;
 if(step==='impact')panel.innerHTML=`<div class="demo-grid"><div><p class="eyebrow">LINKED CONTEXT</p><h3>One capability.<br>Three customer reports.</h3><p>The issue and reports share the subscription part. Ticket account links identify the customers that need follow-up.</p><div class="constraint"><strong>Keep the claim precise.</strong><p>A shared part supports this investigation. It does not prove a shared worker, a causal ticket-to-issue link, or a revenue-loss figure.</p></div><button class="next" data-next="plan">Review the proposed work →</button></div><div class="map"><button class="map-node" ${known?'data-evidence="ISS-031"':'data-next="evidence"'}><strong>${known?'ISS-42 · Existing investigation':'Existing investigation not retrieved'}</strong><small>${known?'Source ISS-031 · routing and safe replay':'Cause and routing plan remain unconfirmed'}</small></button><div class="arrow">shared source part ↓</div><div class="map-node"><strong>CAPL-4 · Subscriptions</strong><small>Source PART-003 · product context</small></div><div class="arrow">reports linked to accounts ↓</div><div class="map-branches">${[['TKT-124','TechFlow','TKT-50'],['TKT-125','GlobalCommerce','TKT-52'],['TKT-126','GlobalMart','TKT-53']].map(([id,name,native])=>`<button class="map-node" data-evidence="${id}"><strong>${name}</strong><small>${native} · open report</small></button>`).join('')}</div><p class="small">Select a node to read its source. These are context links, not a measured dependency graph.</p></div></div>`;
 if(step==='plan')panel.innerHTML=`<div class="demo-grid"><div><p class="eyebrow">COORDINATED INVESTIGATION</p><h3>${known?'Validate recovery<br>before the change.':'Find the cause<br>before a routing plan.'}</h3><p>${known?'Reuse ISS-42 as incident context. Prepare scoped checks with evidence and current authorized owners.':'Customer symptoms support investigation. They do not establish a safe rerouting procedure. Retrieve the missing issue and verify the diagnosis first.'}</p><span class="tag">APPROVAL PREVIEW · NO LIVE WRITES</span><label class="review-check"><input id="review-confirm" type="checkbox" ${approved?'checked':''}> I reviewed this preview and its evidence. No work will be created by this site.</label><button id="approve-plan" class="button" ${approved?'':'disabled'}>${approved?'Preview approved':'Approve preview'} <span aria-hidden="true">→</span></button><button id="reset-plan" class="next">Reset preview</button><div id="approval-result" ${approved?'':'hidden'} class="preview-result"><strong>Preview approved.</strong><p>No DevRev work was created. The agent build must return actual created or reused IDs after a valid approval.</p></div></div><div><p class="eyebrow">PROPOSED TASKS</p><div class="task"><strong>1 / ${known?'Verify scheduler and retry behavior':'Retrieve and validate the existing diagnosis'}</strong><p>Read complete records. Check missing attempts, retries, webhooks, and the source date. Live queue data is still missing.</p></div><div class="task"><strong>2 / ${known?'Validate routing and replay safety':'Define recovery checks after diagnosis'}</strong><p>${known?'Test idempotency, missed-job replay, webhook delivery, and no double billing before any runtime action.':'Do not recommend routing from symptoms alone. Define replay and duplicate-charge checks once the source plan is available.'}</p></div><div class="task"><strong>3 / Prepare customer update drafts</strong><p>Link TechFlow, GlobalCommerce, and GlobalMart reports. State confirmed facts, gaps, and the next check. Sending requires approval.</p></div><p class="small" style="margin-top:20px">Current owners must be selected. Source employees are reference data, not automatically authorized work owners.</p></div></div>`;
 $('#demo-status').textContent=known?'Existing investigation included. Source facts remain separate from runtime checks.':'Existing investigation removed. Recommendation limited to the available customer evidence.';
}
function showEvidence(id){
 const e=snapshot.evidence.find(x=>x.sourceId===id);
 $('#evidence-title').textContent=e.title;
 $('#evidence-meta').textContent=`${e.nativeId} · source ${e.sourceId} · ${e.date?e.date.slice(0,10)+' · ':''}${e.path} · ${e.locator}`;
 $('#evidence-body').textContent=e.body;
 $('#evidence-dialog').showModal();
}
function renderInventory(){
 const query=$('#data-search').value.toLowerCase(), filter=$('#data-filter').value;
 const rows=snapshot.inventory.filter(r=>(filter==='all'||filter===r.coverage)&&`${r.title} ${r.note}`.toLowerCase().includes(query));
 if(!rows.some(r=>r.title===selectedInventory))selectedInventory=rows[0]?.title;
 $('#inventory-rows').innerHTML=rows.map(r=>`<tr class="${r.title===selectedInventory?'selected':''}"><td><button data-inventory="${escapeHtml(r.title)}" aria-pressed="${r.title===selectedInventory}">${escapeHtml(r.title)}</button></td><td>${fmt(r.loaded)}${r.coverage==='metadata'?'*':''}</td><td>${fmt(r.source)}</td><td>${r.coverage==='full'?'Full':r.coverage==='partial'?'Partial':'Metadata / timeline'}</td></tr>`).join('');
 $('#inventory-status').textContent=`${rows.length} of ${snapshot.inventory.length} data families. * Context count, not new employee identities or inbound conversations.`;
 const r=rows.find(x=>x.title===selectedInventory);
 $('#inventory-detail').innerHTML=r?`<p class="eyebrow">MAPPING & LIMITS</p><h3>${escapeHtml(r.title)}</h3><p>${escapeHtml(r.note)}</p><div class="coverage-bar" aria-hidden="true"><span style="width:${Math.round(r.loaded/r.source*100)}%"></span></div><p class="small">${fmt(r.loaded)} of ${fmt(r.source)} source records ${r.coverage==='metadata'?'preserved as context':'loaded'}.</p><p><strong>Find in DevRev</strong><br>${escapeHtml(r.lookup)}</p>`:'<p>No data matches this filter.</p>';
}
function selectIntegration(id){
 const item=integrations.find(x=>x.id===id);
 document.querySelectorAll('[data-integration]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.integration===id)));
 $('#integration-detail').innerHTML=`<p class="eyebrow">${escapeHtml(item.state)}</p><h3>${escapeHtml(item.headline)}</h3><p>${escapeHtml(item.purpose)}</p>${[['Route',item.route],['Setup',item.setup],['Next check',item.check],['Effort',item.cost]].map(([key,value])=>`<div class="detail-line"><span>${key}</span><p>${escapeHtml(value)}</p></div>`).join('')}`;
}
function selectAgent(id){
 const a=agents.find(x=>x.id===id);
 document.querySelectorAll('[data-agent]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.agent===id)));
 $('#agent-detail').innerHTML=`<div><p class="eyebrow">PROPOSED STAGE</p><h3>${escapeHtml(a.title)}</h3><p>${escapeHtml(a.body)}</p></div><div><p class="small">TOOLS / CONTRACT</p><code>${escapeHtml(a.tools)}</code><p style="margin-top:15px"><strong>Output:</strong> ${escapeHtml(a.output)}</p><p><strong>Check:</strong> ${escapeHtml(a.check)}</p></div>`;
}
async function init(){
 try{
  const response=await fetch('snapshot.json');if(!response.ok)throw new Error('Snapshot unavailable');snapshot=await response.json();
  renderDemo();renderInventory();
  $('#integration-list').innerHTML=integrations.map(i=>`<button class="choice" data-integration="${i.id}" aria-pressed="false"><span>${i.name}</span><small>${i.effort}</small></button>`).join('');selectIntegration('devrev');
  $('#agent-flow').innerHTML=agents.map((a,i)=>`<button data-agent="${a.id}" aria-pressed="false"><small>0${i+1}</small><strong>${a.name}</strong></button>`).join('');selectAgent('scope');
  document.addEventListener('click',event=>{
   const b=event.target.closest('button');if(!b)return;
   if(b.dataset.step)setStep(b.dataset.step);
   if(b.dataset.next){setStep(b.dataset.next);$(`#tab-${b.dataset.next}`).focus();}
   if(b.dataset.evidence)showEvidence(b.dataset.evidence);
   if(b.dataset.inventory){selectedInventory=b.dataset.inventory;renderInventory();document.querySelector(`[data-inventory="${selectedInventory}"]`)?.focus();}
   if(b.dataset.integration)selectIntegration(b.dataset.integration);
   if(b.dataset.agent)selectAgent(b.dataset.agent);
   if(b.id==='close-evidence')$('#evidence-dialog').close();
   if(b.id==='approve-plan'){approved=true;$('#approval-result').hidden=false;b.textContent='Preview approved';$('#demo-status').textContent='Preview approved. No work was created and no messages were sent.';}
   if(b.id==='reset-plan'){approved=false;renderDemo();$('#demo-status').textContent='Preview reset. No work was created.';$('#review-confirm').focus();}
  });
  document.addEventListener('change',event=>{if(event.target.id==='review-confirm')$('#approve-plan').disabled=!event.target.checked;});
  $('#history-toggle').addEventListener('change',event=>{includeHistory=event.target.checked;approved=false;renderDemo();});
  $('#data-search').addEventListener('input',renderInventory);$('#data-filter').addEventListener('change',renderInventory);
  $('.tabs').addEventListener('keydown',event=>{
   if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
   event.preventDefault();let i=steps.indexOf(step);
   i=event.key==='Home'?0:event.key==='End'?steps.length-1:(i+(event.key==='ArrowRight'?1:-1)+steps.length)%steps.length;
   setStep(steps[i]);$(`#tab-${step}`).focus();
  });
 }catch(error){$('#demo-panel').textContent='The data snapshot could not load. Refresh the page or use the handoff documents.';$('#demo-status').textContent='Snapshot unavailable; no preview actions are enabled.';}
}
init();
